begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into public.organizations(slug,name) values('kafou','KAFOU') on conflict do nothing;
insert into auth.users(id,email,raw_user_meta_data) values
('10000000-0000-0000-0000-000000000001','parent1@example.test','{"role":"super_admin","name":"Parent One"}'),
('10000000-0000-0000-0000-000000000002','parent2@example.test','{"name":"Parent Two"}'),
('10000000-0000-0000-0000-000000000003','staff@example.test','{"name":"Staff"}'),
('10000000-0000-0000-0000-000000000004','head@example.test','{"name":"Head Office"}');
insert into public.branches(id,slug,name) values('20000000-0000-0000-0000-000000000001','test-one','Test One'),('20000000-0000-0000-0000-000000000002','test-two','Test Two');
insert into public.role_assignments values('10000000-0000-0000-0000-000000000003','branch'),('10000000-0000-0000-0000-000000000004','super_admin');
insert into public.branch_permissions values('10000000-0000-0000-0000-000000000003','20000000-0000-0000-0000-000000000001');
insert into public.families(id,name) values('30000000-0000-0000-0000-000000000001','Family One'),('30000000-0000-0000-0000-000000000002','Family Two');
insert into public.guardians values('30000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001'),('30000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000002');
insert into public.family_branches values('30000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001'),('30000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000002');
insert into public.children(id,family_id,name,reported_age) values('40000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001','Child One',8);
insert into public.child_sports(child_id,sport,level,status) values('40000000-0000-0000-0000-000000000001','swimming','L3','reviewed'),('40000000-0000-0000-0000-000000000001','football','L1','reviewed');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1","user_metadata":{"role":"super_admin"}}',true);
select is((select count(*)::int from public.families),1,'Parent sees own family only');
select is((select count(*)::int from public.role_assignments where role='super_admin'),0,'Forged metadata grants no role');
select is((select count(*)::int from public.child_sports),2,'Child holds independent sport levels');
select throws_ok($$select public.academy_command('family.update','{"id":"30000000-0000-0000-0000-000000000002","name":"Stolen"}')$$,'42501',null,'Cannot mutate another family');
select throws_ok($$insert into public.role_assignments values(auth.uid(),'admin')$$,'42501',null,'Direct privilege escalation denied');
select throws_ok($$update public.audit_events set action='hidden'$$,'42501',null,'Audit immutable to user');
select throws_ok($$select public.academy_command('child.sport','{"child_id":"40000000-0000-0000-0000-000000000001","sport":"karate","level":"L5"}')$$,'42501',null,'Parent cannot assign reviewed level');
select throws_ok($$select public.academy_command('branch.save','{"slug":"fraud","name":"Fraud"}')$$,'42501',null,'Parent cannot configure branch');
select lives_ok($$select public.submit_enquiry('{"parentName":"Parent One","mobile":"+971501234567","childName":"Child One","age":"8","sport":"swimming","experience":"unsure","preferredBranch":"test-one"}','50000000-0000-0000-0000-000000000001')$$,'Enquiry transaction succeeds');
select lives_ok($$select public.submit_enquiry('{"parentName":"Parent One","mobile":"+971501234567","childName":"Child One","age":"8","sport":"swimming","experience":"unsure","preferredBranch":"test-one"}','50000000-0000-0000-0000-000000000001')$$,'Duplicate retries succeed idempotently');
select is((select count(*)::int from public.trial_enquiries),1,'One enquiry after retry');
select throws_ok($$select public.submit_enquiry('{"parentName":"Parent One","mobile":"+971501234567","childName":"Other Child","age":"8","sport":"swimming"}','50000000-0000-0000-0000-000000000001')$$,'23505',null,'Changed payload rejects reused key');
select throws_ok($$select public.submit_enquiry('{"parentName":"Parent One","mobile":"+971501234567","childName":"Child One","age":"99","sport":"swimming","experience":"unsure"}','50000000-0000-0000-0000-000000000002')$$,'23514',null,'Invalid child age rolls back transaction');
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000003","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.families),1,'Branch sees explicitly linked family');
select is((select count(*)::int from public.leads),1,'Branch sees own enquiry');
select throws_ok($$select public.academy_command('family.update','{"id":"30000000-0000-0000-0000-000000000002","name":"Stolen"}')$$,'42501',null,'Cross-branch writes denied');
reset role;
update public.profiles set active=false where id='10000000-0000-0000-0000-000000000003';
set local role authenticated;
select is((select count(*)::int from public.families),0,'Suspension immediately revokes access');
reset role;
update public.profiles set active=true where id='10000000-0000-0000-0000-000000000003';
delete from public.branch_permissions where user_id='10000000-0000-0000-0000-000000000003';
set local role authenticated;
select is((select count(*)::int from public.leads),0,'Branch revocation immediate without new JWT');
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000004","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.families),0,'Super administrator requires MFA');
select throws_ok($$select public.academy_command('staff.access','{}')$$,'42501',null,'Permission changes require MFA');
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000004","role":"authenticated","aal":"aal2"}',true);
select is((select count(*)::int from public.families where id in ('30000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002')),2,'MFA administrator sees authorized organization');
select is((select count(*)::int from public.leads where parent_name='Parent One'),1,'Failed submission left no partial lead');
set local role anon;
select throws_ok($$select * from public.families$$,'42501',null,'Anonymous cannot read families');
select throws_ok($$select public.submit_enquiry('{}',gen_random_uuid())$$,'42501',null,'Anonymous cannot bypass server submission guard');
reset role;
insert into public.role_assignments values('10000000-0000-0000-0000-000000000004','branch');
insert into public.branch_permissions values('10000000-0000-0000-0000-000000000004','20000000-0000-0000-0000-000000000001');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000004","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.families),0,'Mixed super admin and branch roles cannot bypass MFA');
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select public.submit_enquiry('{"parentName":"Parent One","mobile":"+971501234567","childName":"Child One","childId":"40000000-0000-0000-0000-000000000001","age":"8","sport":"swimming","experience":"unsure","preferredBranch":"test-one"}','50000000-0000-0000-0000-000000000003');
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000004","role":"authenticated","aal":"aal2"}',true);
select public.academy_command('lead.convert',jsonb_build_object('id',(select lead_id from public.trial_enquiries where child_id='40000000-0000-0000-0000-000000000001')));
select is((select count(*)::int from public.trial_enquiries where child_id='40000000-0000-0000-0000-000000000001'),1,'Conversion preserves existing child');
select lives_ok($$select public.academy_command('child.sport','{"child_id":"40000000-0000-0000-0000-000000000001","sport":"swimming","level":"L4"}')$$,'Head office can review an existing sport');
select is((select level from public.child_sports where child_id='40000000-0000-0000-0000-000000000001' and sport='football'),'L1','Updating swimming leaves football independent');
reset role;
delete from public.role_assignments where user_id='10000000-0000-0000-0000-000000000001' and role='parent';
insert into public.role_assignments values('10000000-0000-0000-0000-000000000001','coach');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000001","role":"authenticated","aal":"aal1"}',true);
select is((select count(*)::int from public.children),0,'Removed parent role cannot use old guardian grant');
select throws_ok($$select public.academy_command('family.update','{"id":"30000000-0000-0000-0000-000000000001","name":"Stolen"}')$$,'42501',null,'Coach cannot modify former guardian family');
reset role;
update auth.users set email_confirmed_at=now() where id='10000000-0000-0000-0000-000000000002';
insert into public.staff_invitations(id,email,role,branch_ids,invited_by,auth_user_id,expires_at) values('60000000-0000-0000-0000-000000000001','parent2@example.test','coach',array['20000000-0000-0000-0000-000000000001']::uuid[],'10000000-0000-0000-0000-000000000004','10000000-0000-0000-0000-000000000002',now()-interval '1 hour');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"10000000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal1"}',true);
select throws_ok($$select public.academy_command('invitation.accept','{"id":"60000000-0000-0000-0000-000000000001"}')$$,'42501',null,'Expired invitation cannot grant role');
reset role;
update public.staff_invitations set expires_at=now()+interval '1 hour' where id='60000000-0000-0000-0000-000000000001';
set local role authenticated;
select lives_ok($$select public.academy_command('invitation.accept','{"id":"60000000-0000-0000-0000-000000000001"}')$$,'Verified recipient can accept scoped invitation');
select throws_ok($$select public.academy_command('invitation.accept','{"id":"60000000-0000-0000-0000-000000000001"}')$$,'42501',null,'Used invitation cannot be reused');
select * from finish();
rollback;
